package cli

import (
	"os"
	"path/filepath"
	"regexp"
	"strings"
	"testing"
)

func TestZZSum(t *testing.T) {
	re := regexp.MustCompile(`^\[module\]|<- .* (fail|error) |^Result|step\(s\)|--- FAIL|belongs to another user|timeout after`)
	for _, n := range []string{"validate-module.log", "validate-project.log"} {
		raw, err := os.ReadFile(filepath.Join(os.Getenv("TMPDIR"), n))
		if err != nil {
			t.Fatal(err)
		}
		t.Log("### " + n)
		seen := map[string]bool{}
		for _, l := range strings.Split(string(raw), "\n") {
			if re.MatchString(l) {
				k := strings.TrimSpace(l)
				if i := strings.Index(k, " ("); strings.HasPrefix(k, "--- FAIL") && i > 0 {
					k = k[:i]
				}
				if strings.Contains(k, "belongs to") {
					k = "env: belongs to another user"
				}
				if !seen[k] {
					seen[k] = true
					t.Log(k)
				}
			}
		}
	}
}
EOF
